using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
namespace CuteMouseEffects{class MagicCursorPicker:Control{string selectedId="swirl",themeId="warm";int hot=-1;public event EventHandler SelectionChanged;public string SelectedId{get{return selectedId;}set{string id=CursorShapes.Find(value).Id;if(id==selectedId)return;selectedId=id;Invalidate();}}public string ThemeId{get{return themeId;}set{string id=EffectThemes.Find(value).Id;if(id==themeId)return;themeId=id;Invalidate();}}public MagicCursorPicker(){Cursor=Cursors.Hand;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);}int Hit(Point p){if(p.X<0||p.Y<0||p.X>=Width||p.Y>=Height)return-1;int cw=Math.Max(1,Width/3),ch=Math.Max(1,Height/2),n=(p.Y/ch)*3+p.X/cw;return n>=0&&n<6?n:-1;}protected override void OnMouseMove(MouseEventArgs e){int n=Hit(e.Location);if(n!=hot){hot=n;Invalidate();}base.OnMouseMove(e);}protected override void OnMouseLeave(EventArgs e){hot=-1;Invalidate();base.OnMouseLeave(e);}protected override void OnMouseDown(MouseEventArgs e){if(e.Button==MouseButtons.Left){int n=Hit(e.Location);if(n>=0){SelectedId=CursorShapes.All[n].Id;if(SelectionChanged!=null)SelectionChanged(this,EventArgs.Empty);}}base.OnMouseDown(e);}protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(MagicPalette.Back);g.SmoothingMode=SmoothingMode.AntiAlias;int cw=Width/3,ch=Height/2;var theme=EffectThemes.Find(themeId);for(int i=0;i<6;i++){int col=i%3,row=i/3;var r=new Rectangle(col*cw+4,row*ch+4,cw-9,ch-9);bool chosen=CursorShapes.All[i].Id==selectedId;using(var p=MagicPalette.Round(r,19))using(var b=new SolidBrush(chosen?Color.FromArgb(255,249,239):(i==hot?Color.FromArgb(242,237,227):MagicPalette.Card)))g.FillPath(b,p);if(chosen)using(var p=MagicPalette.Round(new Rectangle(r.X+1,r.Y+1,r.Width-2,r.Height-2),18))using(var q=new Pen(theme.Primary,2.2f))g.DrawPath(q,p);CursorShapes.Draw(g,CursorShapes.All[i].Id,new RectangleF(r.X+14,r.Y+18,66,66),theme.Shadow,theme.Primary,theme.Secondary,theme.Glow,theme.Core);using(var f=new Font("Microsoft YaHei UI",10f,chosen?FontStyle.Bold:FontStyle.Regular))TextRenderer.DrawText(g,CursorShapes.All[i].Name,f,new Rectangle(r.X+90,r.Y+29,r.Width-100,24),MagicPalette.Ink,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding);using(var f=new Font("Microsoft YaHei UI",7.6f))TextRenderer.DrawText(g,CursorShapes.All[i].Description,f,new Rectangle(r.X+90,r.Y+58,r.Width-100,42),MagicPalette.Soft,TextFormatFlags.Left|TextFormatFlags.WordBreak|TextFormatFlags.NoPadding|TextFormatFlags.EndEllipsis);}}}}
